    // [WSCoop] Map markers / teammates: icons that follow a location rather than an actor.
    void WSSetTargetLocation(const FVector& InLocation)
    {
        TargetLocation = InLocation;
    }

    // [WSCoop] Name and distance shown under the icon at all times. False = this icon has no name text.
    bool WSSetLabel(const FString& Label, const FString& DistanceText)
    {
        if (Text_MarkerName == nullptr)
            return false;
        Text_MarkerName.SetText(FText::FromString(Label));
        Text_MarkerName.SetVisibility(ESlateVisibility::HitTestInvisible);
        if (Text_Distance != nullptr)
        {
            Text_Distance.SetText(FText::FromString(DistanceText));
            Text_Distance.SetVisibility(ESlateVisibility::HitTestInvisible);
        }
        return true;
    }

// [WSCoop] Map markers and teammates keep their name and distance visible.
if (WSMapMarkers::IsPinnedIcon(this))
    return;
